update public.settings set data = $j$[{"img": "/samples/banner-laptops.jpg", "kicker": "New in stock", "title": "Business laptops, ready to work.", "text": "EliteBook, ThinkPad and MacBook, checked and covered by a 12-month warranty.", "btn": "Shop laptops", "link": "#/shop?cat=Laptops", "overlay": "left", "on": true}, {"img": "/samples/banner-phones.jpg", "kicker": "Phones", "title": "The latest phones, delivered.", "text": "Samsung Galaxy and iPhone, delivered across Accra by our own riders.", "btn": "Shop phones", "link": "#/shop?cat=Phones", "overlay": "left", "on": true}]$j$::jsonb, updated_at = now() where key = 'banners' and data = '[]'::jsonb;
select (select count(*) from public.products) products, (select count(*) from public.units where status='in_stock') in_stock, (select jsonb_array_length(data) from public.settings where key='banners') banners;
